"""Telegram terminal UX. Shell text is **never** generated by the LLM.

Limited commands run as separate low-privilege tosbot-terminal systemd jobs.
Root commands require an active root-helper-validated TOTP session (5 minutes).
"""
from __future__ import annotations
import hashlib
import json
import os
import re
import subprocess
import time
from pathlib import PurePosixPath
from typing import Any

BROKER = '/usr/local/sbin/tosbot-ai-admin-ctl'
CONFIRM_TTL = 90
ROOT_TTL = 300
# These prefixes are interpreted literally. A free-form conversation is NOT shell text.
SHELL_HEADS = {'ping','mkdir','ls','ll','pwd','tree','cd','cat','head','tail','grep','find',
               'df','du','free','uptime','ps','top','htop','ip','ss','curl','wget','dig',
               'whoami','id','uname','date','hostname','journalctl','systemctl',
               'apt','apt-get','dpkg','sudo','touch','cp','mv','rm','rmdir','chmod',
               'chown','echo','printf','sed','awk','wc','sort','stat','mount','umount',
               'nano','vi','vim','bash','sh','python','python3','pip','pip3','git',
               'docker','docker-compose','docker','podman','tar','unzip','zip','traceroute',
               'traceroute6','traceroute','reboot','shutdown','su','useradd','userdel',
               'ufw','iptables','nft','kill','pkill','killall','crontab','nc','netcat'}
ROOT_DEFAULT = {'apt','apt-get','dpkg','reboot','shutdown','ufw','iptables','nft',
                'mount','umount','useradd','userdel','systemctl','su','sudo'}
DANGEROUS_RE = re.compile(r'(?i)(?:\brm\b|\bmkfs\b|\bdd\b|\bchmod\b|\bchown\b|'
                          r'\buserdel\b|\bshutdown\b|\breboot\b|\bpoweroff\b|'
                          r'\bapt(?:-get)?\s+(?:upgrade|full-upgrade|dist-upgrade|remove|purge|autoremove)\b|'
                          r'\b(docker|podman)\s+(?:system\s+prune|rm|rmi)\b|'
                          r'\b(?:systemctl)\s+(?:stop|disable|restart)\b|'
                          r'\b(?:mv|truncate|wipefs)\b|\b(?:kill|pkill|killall)\b|'
                          r'\b(?:sudo\s+su|su\s+-)\b|[;&|`$><])')


def safe_root_readonly(cmd: str) -> bool:
    """Only an exact, intentionally small set bypasses *second* confirmation.

    Root TOTP is still required. Never classify `python`, `bash`, pipelines or
    commands with options that could write/change state as read-only.
    """
    return cmd.strip() in {
        'whoami', 'id', 'id -u', 'id -un', 'id -g', 'id -gn',
        'pwd', 'uptime', 'hostname', 'date', 'date -Is',
        'uname', 'uname -a', 'uname -r', 'df', 'df -h',
        'free', 'free -h',
    }


def literal_shell(text: str) -> bool:
    """Only unambiguous bare Unix commands are terminal input."""
    if not text or text.startswith('/') or '\n' in text:
        return False
    first = text.split(maxsplit=1)[0]
    return first in SHELL_HEADS and text == text.lstrip()


# A natural-language command must never be forwarded unchanged to bash.
# Route common read-only ping phrasings through a bounded, validated form.
PING_COUNTS = {
    'satu':1, 'dua':2, 'tiga':3, 'empat':4, 'lima':5, 'enam':6,
    'tujuh':7, 'delapan':8, 'sembilan':9, 'sepuluh':10,
    'siji':1, 'loro':2, 'telu':3, 'papat':4, 'limo':5,
    'kalih':2, 'sekawan':4,
}
PING_HUMAN = re.compile(
    r'(?i)^ping\s+(?:ke\s+)?(?P<host>[a-z0-9][a-z0-9.\-:]{0,252})'
    r'(?:\s+(?:sebanyak\s+)?(?P<count>\d{1,3}|[a-z]+)\s*(?:kali|x|paket))?\s*$'
)
PING_MAX_COUNT = 10


def _normalized_ping_command(text: str) -> str:
    """Translate a simple ping request without asking AI to synthesize shell.

    Explicit flag-based shell syntax is preserved. Natural-language ping syntax
    is strict: unrecognized words cause a helpful error, not a bash execution.
    """
    if not re.match(r'(?i)^ping\s', text):
        return text
    rest = text[5:].strip()
    if rest.startswith('-'):
        return text  # e.g. ping -c 4 google.com (explicit CLI form)
    parsed = PING_HUMAN.fullmatch(text)
    if parsed:
        host = parsed.group('host')
        # Only an ASCII DNS hostname or a numeric literal; no metacharacters.
        if (len(host)>253 or host.startswith('-') or '..' in host or
                host.endswith('-') or any(part.startswith('-') or part.endswith('-')
                for part in host.split('.'))):
            raise ValueError('Nama host tidak valid.')
        raw = (parsed.group('count') or '4').lower()
        if raw.isdecimal():
            n = int(raw)
        else:
            n = PING_COUNTS.get(raw)
        if n is None or not (1 <= n <= PING_MAX_COUNT):
            raise ValueError('Jumlah ping harus 1 sampai 10 kali.')
        return f'ping -n -c {n} -W 2 -w 20 {host}'
    # Explicit shell syntax with additional flags can be used via /sh.
    raise ValueError('Format ping tidak dikenali. Contoh: "ping ke google.com sebanyak 4 kali" atau "ping -c 4 google.com".')


def normalize_command(text: str) -> str:
    t = text.strip()
    if re.match(r'(?i)^ping\s',t):
        return _normalized_ping_command(t)
    if re.fullmatch(r'apt\s+update',t):
        return 'apt-get update'
    if re.fullmatch(r'apt\s+upgrade',t):
        return 'apt-get upgrade -y'
    if t == 'top':
        return 'top -b -n 1'
    # Some VPS lack bash aliases for ll.
    if t == 'll':
        return 'ls -lah'
    return t


def terminal_path(arg: str, cwd: str) -> str:
    target = (arg or '').strip().strip('"\'')
    if target in ('~','home'):
        return '/home'
    if not target:
        return cwd
    if target == '-':
        return cwd
    p = PurePosixPath(target if target.startswith('/') else cwd.rstrip('/') + '/' + target)
    parts = []
    for part in str(p).split('/'):
        if part in ('','.'): continue
        if part == '..':
            if parts: parts.pop()
        else:
            parts.append(part)
    return '/' + '/'.join(parts)


def broker(action: str, packet: dict|None=None, job_id: str|None=None) -> dict:
    argv = ['sudo','-n',BROKER,action]
    if job_id: argv.append(job_id)
    try:
        cp = subprocess.run(argv,input=json.dumps(packet or {},ensure_ascii=False),text=True,
                            capture_output=True,timeout=18,env={
                                'PATH':'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin',
                                'LANG':'C.UTF-8'})
        # No sensitive input is included in error responses.
        data=json.loads(cp.stdout.strip().splitlines()[-1])
        if not isinstance(data,dict): raise ValueError('bad response')
        return data
    except Exception:
        return {'ok':False,'error':'Gagal menghubungi helper admin. Cek instalasi dan journalctl.'}


class Terminal:
    def __init__(self,settings, store):
        self.s=settings
        self.db=store

    def _session(self) -> str|None:
        session=self.db.get_kv('term_admin_session') or {}
        if int(session.get('expires',0)) <= int(time.time()):
            self.db.set_kv('term_admin_session',None)
            return None
        return session.get('token')

    def _cwd(self):
        return self.db.get_kv('term_cwd','/home') or '/home'

    def _remember_job(self, job_id,mode,cmd):
        jobs=self.db.get_kv('term_jobs',[]) or []
        jobs.append({'id':job_id,'mode':mode,'at':int(time.time()),
                     'cmdhash':hashlib.sha256(cmd.encode()).hexdigest()[:16]})
        self.db.set_kv('term_jobs',jobs[-30:])
        self.db.audit(self.s.owner_id,'admin_terminal_'+mode,job_id+' '+jobs[-1]['cmdhash'])

    def _execute(self,cmd,mode):
        try:
            cmd=normalize_command(cmd)
        except ValueError as exc:
            return '❌ '+str(exc)
        # Telegram messages are not a TTY. Reject interactive programs instead
        # of leaving root jobs waiting indefinitely for a terminal prompt.
        lead=cmd.split(maxsplit=1)[0] if cmd else ''
        if lead in {'nano','vi','vim','htop'} or cmd in {'sudo su','sudo -i','su','su -','bash','sh'}:
            return ('Perintah ini membutuhkan terminal interaktif (TTY), yang tidak disediakan Telegram. '
                    'Gunakan perintah noninteraktif atau SSH/Tailscale untuk editor/shell interaktif.')
        if not cmd or len(cmd)>2048 or '\n' in cmd or '\r' in cmd:
            return 'Perintah tidak valid (maksimum 2048 karakter, satu baris).'
        data={'mode':mode,'command':cmd,'cwd':self._cwd()}
        if mode=='root':
            token=self._session()
            if not token:
                return ('🔐 Belum ada sesi administrator. Kirim `sudo su`, lalu autentikasi '
                        'dengan `/auth 123456` (kode dari aplikasi TOTP, bukan password VPS).')
            data['session']=token
        res=broker('submit',data)
        if not res.get('ok'):
            return '⛔ Eksekusi gagal: '+str(res.get('error','helper tidak tersedia'))
        job=res['job_id']
        self._remember_job(job,mode,cmd)
        # No false success: queued != done. Output will be reported when worker completes.
        return f'⏳ Menjalankan ({"root" if mode=="root" else "terbatas"}): `{cmd[:180]}`\nJob: `{job}`\nKetik `/job {job}` untuk memeriksa hasil.'

    def _root_command(self,cmd):
        if not self._session():
            return ('🔐 Mode root belum aktif. Kirim `sudo su`, lalu balas `/auth <kode TOTP>`.'
                    '\nPertama kali: aktivasi TOTP via SSH dengan `sudo /usr/local/sbin/tosbot-ai-admin-ctl setup`.')
        # Command-string heuristics are unsafe (a script can conceal writes).
        # Confirm all root commands except a very small exact read-only set.
        if not safe_root_readonly(cmd):
            token=os.urandom(3).hex()
            session=self._session() or ''
            bound=hashlib.sha256(session.encode()).hexdigest()[:24]
            self.db.set_kv('term_pending_root',{'command':cmd,'expires':int(time.time())+CONFIRM_TTL,
                                                 'code':token,'session_hash':bound})
            return (f'⚠️ Perintah root memerlukan persetujuan kedua:\n`{cmd[:400]}`\n'
                    f'Belum dijalankan. Balas `/approve {token}` dalam 90 detik untuk menjalankan, '
                    'atau `/cancelcmd` untuk batal.')
        return self._execute(cmd,'root')

    def handle(self, raw: str) -> str|None:
        text=(raw or '').strip()
        if not text:return None
        if text in ('/terminal','/shellhelp'):
            return ('🖥 TosBot Terminal\n'
                    '`/sh <perintah>`: bash sebagai tosbot-terminal (terbatas).\n'
                    '`sudo su`: autentikasi mode root selama 5 menit.\n'
                    '`/sudo <perintah>`: perintah root saat sesi aktif.\n'
                    '`/job <id>`: status/output job.\n'
                    '`/exit`: tutup sesi root, `/cancelcmd`: batalkan perintah tertunda.\n'
                    'Perintah sederhana seperti `ping google.com`, `cd /home`, `ls`, `tree`, '
                    '`apt update` juga dikenali langsung.\n'
                    '⚠️ Bot Telegram bukan terminal terenkripsi ujung-ke-ujung.')
        if text in ('sudo su','sudo -i','su -','/rootlogin'):
            if self._session(): return '🔐 Sesi root masih aktif. Gunakan `/sudo <perintah>` atau `/exit`.'
            return ('🔐 Siap masuk mode administrator (maks. 5 menit).\n'
                    'Balas `/auth <6 angka>` menggunakan kode aplikasi authenticator Anda.\n'
                    'Jika belum diaktifkan, jalankan setup TOTP sekali melalui SSH.')
        if text.startswith('/auth '):
            code=text[6:].strip()
            if not re.fullmatch(r'\d{6}',code):
                return 'Gunakan `/auth 123456` dengan 6 angka dari aplikasi authenticator.'
            res=broker('open',{'code':code})
            if not res.get('ok'):
                return '⛔ Autentikasi gagal: '+str(res.get('error','sesi tidak dibuka'))
            self.db.set_kv('term_admin_session',{'token':res['session'],
                                                'expires':int(time.time())+int(res.get('expires_in',ROOT_TTL))})
            self.db.audit(self.s.owner_id,'admin_session_open','TOTP validated by privileged helper')
            return ('✅ Sesi root aktif selama 5 menit. Kirim `/sudo <perintah>` atau '
                    'perintah Linux langsung. Ketik `/exit` untuk menutup sesi.')
        if text in ('/exit','exit root'):
            token=self._session()
            if token: broker('close',{'session':token})
            self.db.set_kv('term_admin_session',None)
            self.db.set_kv('term_pending_root',None)
            return '🔒 Sesi administrator ditutup.'
        if text in ('/cancelcmd','/batalshell'):
            self.db.set_kv('term_pending_root',None)
            return 'Perintah root tertunda dibatalkan.'
        match=re.fullmatch(r'/approve\s+([0-9a-f]{6})',text)
        if match:
            p=self.db.get_kv('term_pending_root') or {}
            self.db.set_kv('term_pending_root',None)
            session=self._session() or ''
            actual=hashlib.sha256(session.encode()).hexdigest()[:24] if session else ''
            if (p.get('code')!=match.group(1) or int(p.get('expires',0))<int(time.time())
                    or not session or p.get('session_hash')!=actual):
                return 'Persetujuan tidak valid, sesi berubah, atau sudah kedaluwarsa.'
            return self._execute(p['command'],'root')
        match=re.fullmatch(r'/job(?:\s+([0-9a-f]{20}))?',text)
        if match:
            jobs=self.db.get_kv('term_jobs',[]) or []
            selected=match.group(1) or (jobs[-1]['id'] if jobs else '')
            if not selected or not any(j['id']==selected for j in jobs):
                return 'Tidak ada job dengan ID tersebut.'
            return self.format_status(broker('status',{'session':self._session() or ''},job_id=selected))
        if text == '/jobs':
            jobs=(self.db.get_kv('term_jobs',[]) or [])[-10:]
            return '\n'.join('• '+j['id']+' ['+j['mode']+']' for j in jobs) or 'Belum ada job.'
        if text in ('/cd','/pwd'):
            return '📍 Direktori terminal: '+self._cwd()
        match=re.fullmatch(r'cd(?:\s+(.+))?',text)
        if match:
            path=terminal_path(match.group(1) or '~',self._cwd())
            # Path is a virtual working directory. OS checks permissions at job execution.
            if len(path)>240:
                return 'Path terlalu panjang.'
            self.db.set_kv('term_cwd',path)
            return '📍 Direktori kerja terminal: '+path+'\n(Pastikan path tersebut ada sebelum menjalankan perintah.)'
        if text=='pwd':
            return '📍 Direktori kerja terminal: '+self._cwd()
        if text.startswith('/sudo '):
            return self._root_command(text[6:].strip())
        if text.startswith('/sh ') or text.startswith('/bash '):
            return self._execute(text.split(' ',1)[1],'limited')
        if text.startswith('/run '):
            return self._execute(text[5:],'limited')
        # Explicit natural-language requests for shell commands also bypass the AI.
        request=re.match(r'(?i)^(?:tolong\s+)?(?:jalankan|eksekusi)\s+(?:(?:perintah|command)\s+)?(?:bash\s*[: ]\s*)?(.+)$',text)
        if request and literal_shell(request.group(1).strip()):
            text=request.group(1).strip()
        # Common Indonesian request prefix; only for unambiguous ping commands.
        # Do not generalize this prefix to arbitrary shell commands.
        ping_request=re.fullmatch(r'(?is)(?:tolong|coba|mohon)\s+(ping\s+.+)',text)
        if ping_request:
            text=ping_request.group(1).strip()
        # Plain commands run without AI, but only when clearly Unix shell commands.
        if literal_shell(text):
            cmd=text
            if cmd.startswith('sudo ') and cmd not in ('sudo su','sudo -i'):
                return self._root_command(cmd[5:])
            mode='root' if cmd.split(maxsplit=1)[0] in ROOT_DEFAULT else 'limited'
            # During an authenticated root session, bare shell input is evaluated as root,
            # matching the user request for a short-lived root console.
            if self._session():mode='root'
            if mode=='root': return self._root_command(cmd)
            return self._execute(cmd,'limited')
        return None

    @staticmethod
    def format_status(result:dict):
        if not result.get('ok'):
            return '❌ Tidak bisa membaca status job: '+str(result.get('error','helper tidak tersedia'))
        state=result.get('state','unknown')
        code=result.get('exit_code')
        head=f'🖥 Job {result.get("job_id", "")}\nStatus: {state}'
        if code is not None:head+=f' | exit: {code}'
        if result.get('locked'):
            head+='\n🔐 Output root dikunci. Masuk ulang dengan `sudo su` + TOTP untuk membacanya.'
        output=str(result.get('output') or '')[-3100:]
        if output: head+='\n\n'+output
        return head

    def finished_jobs(self):
        jobs=self.db.get_kv('term_jobs',[]) or []
        notified=set(self.db.get_kv('term_notified_jobs',[]) or [])
        messages=[]
        for j in jobs[-20:]:
            if j['id'] in notified: continue
            if len(messages)>=5:break
            result=broker('status',{'session':self._session() or ''},job_id=j['id'])
            if result.get('ok') and result.get('state') in ('done','failed','timed_out'):
                messages.append(self.format_status(result))
                notified.add(j['id'])
        if messages:
            self.db.set_kv('term_notified_jobs',list(notified)[-100:])
        return messages


class TrustedGroupTerminal:
    """Per-grup shell jobs with no per-user TOTP. ONLY for explicitly opted-in
    group IDs checked against root-owned config by the privileged broker.
    Every message requires a real Telegram user and explicit mention, validated
    by bot.py before reaching this class.
    """
    def __init__(self,settings,store,group_id):
        self.s, self.db, self.group_id = settings, store, int(group_id)
        self.prefix = f'trusted_group_{self.group_id}'

    def _get(self, key, default):
        return self.db.get_kv(self.prefix+'_'+key, default)

    def _set(self, key, value):
        self.db.set_kv(self.prefix+'_'+key,value)

    def _cwd(self):
        return self._get('cwd','/home')

    def _packet(self,actor_id):
        return {'group_id':self.group_id,'actor_id':actor_id}

    def _submit(self,cmd,actor_id):
        if not cmd or len(cmd)>2048 or '\n' in cmd or '\r' in cmd:
            return 'Perintah harus satu baris, maksimum 2048 karakter.'
        if cmd in ('nano','vi','vim','htop','bash','sh','sudo su','sudo -i','su','su -'):
            return 'Telegram tidak memiliki TTY persisten. Gunakan command non-interaktif.'
        try:
            cmd = normalize_command(cmd)
        except ValueError as e:
            return '❌ '+str(e)
        res=broker('group-submit', {**self._packet(actor_id), 'mode':'root',
                                    'command':cmd,'cwd':self._cwd()})
        if not res.get('ok'):
            return '❌ Job root grup ditolak: '+str(res.get('error'))
        jobs=self._get('jobs',[]) or []
        jobs.append({'id':res['job_id'], 'actor':actor_id,'at':int(time.time()),
                     'cmdhash':hashlib.sha256(cmd.encode()).hexdigest()[:16]})
        self._set('jobs',jobs[-50:])
        self.db.audit(actor_id,'trusted_group_root',str(self.group_id)+' '+res['job_id'])
        return f'⏳ Admin grup menjalankan sebagai root: `{cmd[:180]}`\nJob: `{res["job_id"]}`\nKetik `/job {res["job_id"]}` untuk output.'

    def handle(self,raw,actor_id):
        text=(raw or '').strip()
        if not text:
            return None
        if text in ('/terminal','/shellhelp','/help'):
            return ('🖥 Trusted Group Console (root). Semua anggota grup terpilih bisa\n'
                    'kirim `@bot /sudo <cmd>` atau `@bot /sh <cmd>` dan dapat melihat hasil di grup.\n'
                    'Perintah bebas tidak memerlukan TOTP. Risiko kehilangan data/ambil alih VPS sangat tinggi.')
        if text in ('sudo su','sudo -i','su -','/rootlogin'):
            return '✅ Hak root sudah aktif otomatis di grup ini. Kirim perintah non-interaktif.'
        if text in ('/auth','/exit','/cancelcmd') or text.startswith('/auth ') or text.startswith('/approve '):
            return 'Trusted group tidak membutuhkan autentikasi atau approval terpisah.'
        m=re.fullmatch(r'/job(?:\s+([0-9a-f]{20}))?',text)
        if m:
            jobs=self._get('jobs',[]) or []
            selected=m.group(1) or (jobs[-1]['id'] if jobs else '')
            if not any(j['id']==selected for j in jobs):
                return 'Job tersebut tidak ditemukan dalam grup ini.'
            return Terminal.format_status(broker('group-status',self._packet(actor_id),job_id=selected))
        if text=='/jobs':
            return '\n'.join('• '+j['id'] for j in (self._get('jobs',[]) or [])[-10:]) or 'Belum ada job.'
        m=re.fullmatch(r'cd(?:\s+(.+))?',text)
        if m:
            cwd=terminal_path(m.group(1) or '~',self._cwd())
            if len(cwd)>240: return 'Direktori terlalu panjang.'
            self._set('cwd',cwd)
            return '📍 Direktori kerja grup: '+cwd
        if text in ('pwd','/pwd','/cd'):
            return '📍 Direktori kerja grup: '+self._cwd()
        if text.startswith(('/sudo ','/sh ','/bash ','/run ')):
            command=text.split(' ',1)[1]
            if command.startswith('sudo '):command=command[5:]
            return self._submit(command,actor_id)
        # bare sudo command is accepted directly as root
        if literal_shell(text):
            return self._submit(text[5:] if text.startswith('sudo ') else text,actor_id)
        return None

    def finished_jobs(self):
        jobs=self._get('jobs',[]) or []
        notified=set(self._get('notified',[]) or [])
        results=[]
        for j in jobs[-30:]:
            if j['id'] in notified:continue
            if len(results)>=5:break
            res=broker('group-status',self._packet(j['actor']),job_id=j['id'])
            if res.get('ok') and res.get('state') in ('done','failed','timed_out'):
                results.append(Terminal.format_status(res))
                notified.add(j['id'])
        if results:
            self._set('notified',list(notified)[-150:])
        return results
